WITH valid AS (SELECT id, device_code, reading_ts, humidity, pressure, status_bits, firmware, ROUND(status_bits, 0) AS status_bits_rounded, pressure + status_bits AS pressure_plus_status_bits FROM device_readings WHERE pressure >= 995), scored AS (SELECT id, reading_ts, status_bits_rounded, AVG(pressure) OVER (ORDER BY status_bits, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS pressure_avg_6, STDDEV_SAMP(pressure) OVER (PARTITION BY device_code) AS device_code_stddev_samp_pressure, STDDEV_SAMP(status_bits) OVER (PARTITION BY device_code) AS device_code_stddev_samp_status_bits, LEAD(status_bits, 1, 0) OVER (ORDER BY pressure_plus_status_bits, id) AS next_status_bits, SUM(status_bits) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS status_bits_sum_2h FROM valid WHERE status_bits_rounded > 67), filtered AS (SELECT id, reading_ts, status_bits_rounded, pressure_avg_6, device_code_stddev_samp_status_bits, status_bits_sum_2h, DATE_TRUNC('month', reading_ts) AS reading_ts_period FROM scored WHERE reading_ts > TO_TIMESTAMP('2025-09-01 05:00:00') AND device_code_stddev_samp_pressure >= 995), with_windows AS (SELECT id, device_code_stddev_samp_status_bits, LAG(status_bits_rounded, 2) OVER (ORDER BY device_code_stddev_samp_status_bits, id) AS prev_status_bits_rounded, ROW_NUMBER() OVER (ORDER BY status_bits_rounded DESC, id) AS row_seq, RANK() OVER (ORDER BY status_bits_sum_2h DESC) AS status_bits_sum_2h_rank FROM filtered) SELECT id, device_code_stddev_samp_status_bits, row_seq, status_bits_sum_2h_rank FROM with_windows
